#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
# Ticket 76's login on a tty: `caminito --session` as caminitotest on a spare tty, on the
# installed packages, with the criteria 72's run on Xvfb couldn't reach. Run it as
# caminitotest, from the copy prepare.sh puts in ~/76-checks, while the session runs:
# over ssh from another machine, which is best since the monitors stay on Caminito, or
# in a MATE Terminal inside the session, or from another tty, switching back to
# Caminito's (Ctrl+Alt+F<n>) to look.
#
# The session ends twice, in stages 14 and 15. A wizard inside the session ends with
# it: run it again from the tty's shell and resume. The results are saved as they're
# given. At the end they're appended to the ticket's notes when this copy can write
# them, and to a file to copy from otherwise.

TOTAL_STAGES=16

HERE="$(dirname "$(realpath "$0")")"
TICKET="${TICKET:-$HERE/../76-tty-login-left-over.md}"
RESULTS=()   # "short name|pass, FAIL, not run or seen|note"
FAILED=()
STATE="${XDG_STATE_HOME:-$HOME/.local/state}/caminito"
PROGRESS="$STATE/76-tty-login.progress"
# The session the results are of: Caminito's pid, when it started and its command line.
SESSION="$STATE/76-tty-login.session"
# Made when stage 14 or 15 asks for a logout, so a wizard run again goes on from there.
LOGOUT_ASKED="$STATE/76-tty-login.logout-asked"
BARE_ASKED="$STATE/76-tty-login.bare-asked"
XRDB_LOGIN="$STATE/76-xrdb-login"
LOG="${SESSION_LOG:-$HOME/session.log}"
DEBUG_CALL=(busctl --user call org.mate.Caminito.Debug /org/mate/Caminito/Debug org.mate.Caminito.Debug)
PACKAGES=(caminito-git mate-session-manager-caminito mate-panel-caminito mate-settings-daemon-caminito)
DEMO_NAMESPACE=caminito-76-demo
CAMINITO_PID=
SINCE=
COMMAND=

# Every login of caminitotest shares one runtime directory and session bus (14), so
# Caminito's are this login's. sudo and su don't set them.
export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
export DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=$XDG_RUNTIME_DIR/bus}"

# session_environment prints what systemd's user manager has of a session's variables.
session_environment() {
  systemctl --user show-environment |
    grep -E '^(WAYLAND_DISPLAY|DISPLAY|MATE_WM_NAME|XDG_SESSION_TYPE|XDG_CURRENT_DESKTOP|XCURSOR_[A-Z]+)=' | sort || true
}
# in_session CMD... runs a command with the displays Caminito exported to systemd.
in_session() {
  # shellcheck disable=SC2046  # one NAME=value word per variable
  env $(systemctl --user show-environment | grep -E '^(WAYLAND_DISPLAY|DISPLAY)=') "$@"
}
# native CMD... starts a Wayland client in the session, detached.
native() { in_session env -u DISPLAY GDK_BACKEND=wayland setsid "$@" >/dev/null 2>&1 & }
# x11 CMD... starts an X11 client on the session's Xwayland, detached.
x11() { in_session env -u WAYLAND_DISPLAY GDK_BACKEND=x11 setsid "$@" >/dev/null 2>&1 & }
# show CMD... runs a command and shows it with its output, indented.
show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@" 2>&1 | sed 's/^/    /' || true; }
# ok "..." prints a check that passed.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# running NAME succeeds when caminitotest runs a process of that name.
running() { pgrep -u "$(id -u)" -x "$1" >/dev/null; }
# bus_started prints when the user's message bus last started, to tell a restart (74).
bus_started() { systemctl --user show dbus.service -p ActiveEnterTimestamp --value 2>/dev/null || true; }
# session_log prints what mate-session and what it starts wrote: the file Caminito's stderr
# went to, and the journal, since mate-session's --debug writes to both.
session_log() {
  [[ -r $LOG ]] && sed 's/\x1b\[[0-9;]*m//g' "$LOG"
  journalctl --user --since "$SINCE" -t mate-session -o cat --no-pager 2>/dev/null || true
}

# dump WHAT prints DumpState's outputs with their layer surfaces, or its windows.
dump() {
  local reply
  reply=$(in_session "${DEBUG_CALL[@]}" --json=short DumpState) || { warn "DumpState didn't answer"; return 0; }
  python3 -c '
import json, sys
state = json.loads(json.loads(sys.argv[2])["data"][0])
rect = lambda r: "%d,%d %dx%d" % (r["x"], r["y"], r["width"], r["height"]) if r else "unmapped"
if sys.argv[1] == "outputs":
    for o in state["outputs"]:
        print("%s: %s at scale %s, work area %s" % (o["name"], rect(o["geometry"]), o["scale"], rect(o["work_area"])))
        for s in o["layer_surfaces"]:
            print("  %-10s %-16s %s, zone %d, keyboard %s" % (
                s["layer"], s["namespace"], rect(s["geometry"]), s["exclusive_zone"], s["keyboard_interactivity"]))
else:
    for w in state["windows"]:
        e = w["frame_extents"]
        print("%s %r: %s, frame %s" % (
            "X11   " if w["xwayland"] else "native", w["title"], rect(w["geometry"]),
            "l%d r%d t%d b%d" % (e["left"], e["right"], e["top"], e["bottom"]) if e else "none"))
' "$1" "$reply" | sed 's/^/    /' || warn "DumpState's reply couldn't be read"
}

# find_session finds the Caminito that runs the session, and waits for its export.
find_session() {
  local exe _
  while true; do
    CAMINITO_PID=$(pgrep -n -x -u "$(id -u)" caminito || true)
    if [[ -n $CAMINITO_PID ]] && tr '\0' ' ' < /proc/"$CAMINITO_PID"/cmdline | grep -q -- '--session'; then
      for _ in $(seq 30); do
        session_environment | grep -q '^WAYLAND_DISPLAY=' && break 2
        sleep 1
      done
      warn "caminito (pid $CAMINITO_PID) exported no WAYLAND_DISPLAY to systemd in 30 s"
    else
      warn "no caminito --session of $(id -un) is running"
    fi
    step "Log in as caminitotest on a spare tty (Ctrl+Alt+F4, for example), and run:"
    step "caminito --session=\"mate-session --debug\" 2>~/session.log"
    pause "Press Enter once the desktop is up"
  done
  SINCE=$(date -d "$(ps -o lstart= -p "$CAMINITO_PID")" '+%F %T')
  COMMAND=$(tr '\0' ' ' < /proc/"$CAMINITO_PID"/cmdline | sed 's/ $//')
  printf '%s\n%s\n%s\n' "$CAMINITO_PID" "$SINCE" "$COMMAND" > "$SESSION"
  # For stage 12, before any stage changes a setting.
  in_session xrdb -query > "$XRDB_LOGIN" 2>&1 || true
  ok "caminito is pid $CAMINITO_PID, started at $SINCE as: $COMMAND"
  exe=$(readlink /proc/"$CAMINITO_PID"/exe 2>/dev/null || true)
  [[ -z $exe || $exe == /usr/bin/caminito ]] || warn "it's $exe, not the installed /usr/bin/caminito"
}
# load_session reads back the session a stopped run found, which may have ended since.
load_session() {
  [[ -s $SESSION ]] || return 0
  { read -r CAMINITO_PID; read -r SINCE; read -r COMMAND; } < "$SESSION" || true
}
# await_exit waits for the session's Caminito to be gone.
await_exit() {
  while [[ -n $CAMINITO_PID ]] && kill -0 "$CAMINITO_PID" 2>/dev/null; do
    warn "caminito (pid $CAMINITO_PID) is still running"
    pause "Press Enter once the session has ended"
  done
}

# record NAME VERDICT NOTE saves a result as it's given.
record() {
  RESULTS+=("$1|$2|$3")
  printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$PROGRESS"
  if [[ $2 == FAIL ]]; then FAILED+=("$1"); fi
}
# result "Short name" records whether the check passed, failed or wasn't run, with
# an optional note.
result() {
  local name="$1" reply="" verdict note=""
  printf '  %s? Did all of it work? (%s) [y]es, [n]o, [s]kipped:%s ' "$YELLOW" "$name" "$RESET"
  read -r reply || true
  case $reply in
    [Yy]*) verdict=pass ;;
    [Ss]*) verdict="not run" ;;
    *) verdict=FAIL ;;
  esac
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  record "$name" "$verdict" "$note"
}

# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$STATE"
  [[ -s $PROGRESS ]] || { rm -f "$SESSION" "$LOGOUT_ASKED" "$BARE_ASKED"; return 0; }
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
    load_session
  else
    rm -f "$PROGRESS" "$SESSION" "$LOGOUT_ASKED" "$BARE_ASKED"
  fi
}

# recorded NAME succeeds when NAME's result is recorded.
recorded() {
  local r
  for r in ${RESULTS[@]+"${RESULTS[@]}"}; do [[ $r == "$1|"* ]] && return 0; done
  return 1
}
# done_already NAME succeeds, and says so, when NAME's result is recorded.
done_already() {
  recorded "$1" || return 1
  say "Already recorded; skipping."
  sleep 1
}

# write_results appends the results to the ticket's notes. caminitotest can't write
# the developer's checkout, so from there they go to a file to copy from.
write_results() {
  local r name verdict note line target="$TICKET"
  [[ -w $target ]] || target="$STATE/76-tty-login-results.md"
  printf '\n- **The login on the tty (%s), on %s (%s), on %s, started as `%s`:**\n' \
    "$(date +%F)" "$(uname -n)" "$(uname -m)" "$(pacman -Q "${PACKAGES[@]}" 2>&1 | paste -sd, | sed 's/,/, /g')" "$COMMAND" >> "$target"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r name verdict note <<< "$r"
    line=$(printf '  - %s: %s.%s' "$name" "$verdict" "${note:+ $note}")
    printf '%s\n' "$line" >> "$target"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$target"
  [[ $target == "$TICKET" ]] ||
    SKIPPED+=("copying $target into ticket 76's notes")
}

banner "Ticket 76: the login on a tty"
load_progress

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before the checks"
[[ $(id -un) == caminitotest ]] || warn "this is $(id -un), not caminitotest, the second user (14)"
show pacman -Q "${PACKAGES[@]}"
for tool in busctl gsettings python3 foot xterm xrdb loginctl journalctl; do
  command -v "$tool" >/dev/null || warn "$tool is missing"
done
python3 -c 'import gi; gi.require_version("GtkLayerShell", "0.1")' 2>/dev/null ||
  warn "gtk-layer-shell's typelib is missing, which stage 11's demo needs"
say "The session runs as caminitotest on a spare tty, with mate-session's phases logged"
say "and Caminito's stderr in a file, so that Caminito logs to the journal:"
step "caminito --session=\"mate-session --debug\" 2>~/session.log"
# A run that already asked for the logout has no session to find.
if [[ -e $LOGOUT_ASKED ]]; then
  say "This run already asked for the logout; going on from there."
  sleep 1
else
  find_session
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The display manager lists MATE on Caminito"
if ! done_already "The display manager lists MATE on Caminito"; then
show pacman -Qo /usr/share/wayland-sessions/mate-caminito.desktop
show grep -E '^(Name|Exec|DesktopNames)=' /usr/share/wayland-sessions/mate-caminito.desktop
show systemctl is-active display-manager.service
step "At the display manager's greeter, the session list has MATE on Caminito."
note "Look only: logging in with it as yourself is 73's, since it shares your user's"
note "systemd manager and bus (14). Skip this if you haven't seen the greeter yet."
result "The display manager lists MATE on Caminito"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The session reaches the desktop, with no phase timing out"
if ! done_already "Reaches the desktop with no phase timing out"; then
for process in mate-session mate-panel caja mate-settings-daemon mate-notification-daemon polkit-mate-authentication-agent-1; do
  if pgrep -u "$(id -u)" -f "(^|/)$process( |\$)" >/dev/null; then ok "$process runs"; else warn "$process isn't running"; fi
done
say "mate-session's phases, in the order it logged them:"
PHASES=$(session_log | grep -E 'GsmManager: (starting|ending) phase' || true)
if [[ -n $PHASES ]]; then
  sed 's/^/    /' <<< "$PHASES"
else
  warn "no phase lines; was the session started with mate-session --debug? Lines with 'phase':"
  session_log | grep -i phase | head -n 20 | sed 's/^/    /' || true
fi
say "Time-outs, in what mate-session and what it starts wrote and in the journal:"
TIMEOUTS=$({ session_log; journalctl --user --since "$SINCE" -o cat --no-pager 2>/dev/null || true; } |
  grep -iE 'timed out|time-?out' | sort | uniq -c || true)
if [[ -n $TIMEOUTS ]]; then sed 's/^/    /' <<< "$TIMEOUTS"; else ok "none"; fi
step "The desktop came up well inside 30 seconds: both panels, the wallpaper, the icons."
note "Expected (08): the phases in order, from STARTUP or EARLY_INITIALIZATION through"
note "INITIALIZATION, WINDOW_MANAGER, PANEL, DESKTOP and APPLICATION to RUNNING, none of"
note "them ended by its 30 s time-out."
result "Reaches the desktop with no phase timing out"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The export to systemd, from a login"
if ! done_already "Exports to systemd from a login"; then
show session_environment
for name in WAYLAND_DISPLAY DISPLAY; do
  if session_environment | grep -q "^$name="; then ok "$name is there"; else warn "$name is missing"; fi
done
if session_environment | grep -qx 'MATE_WM_NAME=Caminito'; then ok "MATE_WM_NAME=Caminito is there"; else warn "MATE_WM_NAME=Caminito is missing"; fi
# Variables that stayed from an earlier session (74) would be there too.
SOCKET="$XDG_RUNTIME_DIR/$(session_environment | sed -n 's/^WAYLAND_DISPLAY=//p')"
if [[ -S $SOCKET ]] && in_session "${DEBUG_CALL[@]}" DumpState >/dev/null 2>&1; then
  ok "$SOCKET is a socket, and Caminito answers on the bus"
else
  warn "$SOCKET isn't a socket, or Caminito doesn't answer: the variables may be an earlier session's"
fi
show loginctl list-sessions --no-pager
note "Expected: the three variables, and a logind session of caminitotest on Caminito's tty."
result "Exports to systemd from a login"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The journal, when stderr isn't the terminal"
if ! done_already "Logs to the journal when stderr isn't the terminal"; then
say "Caminito's stderr is $(readlink /proc/"$CAMINITO_PID"/fd/2 2>/dev/null || echo '(unreadable)')"
for tag in caminito Xwayland caminito-gtk-palette mate-session; do
  say "journalctl --user -t $tag: $(journalctl --user --since "$SINCE" -t "$tag" -o cat --no-pager 2>/dev/null | wc -l) lines"
done
show sh -c "journalctl --user --since '$SINCE' -t caminito -o cat --no-pager | head -n 8"
say "Caminito's warnings and errors:"
journalctl --user --since "$SINCE" -t caminito -p warning -o cat --no-pager 2>/dev/null |
  sed 's/\x1b\[[0-9;]*m//g' | sort | uniq -c | head -n 20 | sed 's/^/    /' || true
if [[ -r $LOG ]]; then
  say "$LOG has $(wc -l < "$LOG") lines, $(grep -c 'caminito' "$LOG" || true) of them naming caminito."
fi
note "Expected: Caminito's lines are in the journal and not in the file, which has"
note "mate-session's and its children's."
result "Logs to the journal when stderr isn't the terminal"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The desktop on each output"
if ! done_already "Desktop icons above the wallpaper on caja's output, the wallpaper alone on the other"; then
say "DumpState's outputs and their layer surfaces:"
dump outputs
step "One output has caja's icons (Computer, Home, Trash) drawn over msd's wallpaper."
step "The other has the wallpaper alone, with no icons and no black or grey fill."
step "On both, the wallpaper fills the output and isn't cut off by a panel."
note "Expected: a mate-background surface in background on every output, and caja's"
note "desktop surface in bottom on one of them (06)."
result "Desktop icons above the wallpaper on caja's output, the wallpaper alone on the other"
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The panel: menus, the window list and the workspace switcher"
if ! done_already "The panel's menus open, and the window list and the switcher answer a click"; then
say "Opening foot and xterm in the session."
native foot
x11 xterm
step "Click Applications, Places and System in the top panel: each menu opens, its"
step "submenus open beside it, and it closes on a click outside or on Escape."
step "Start something from Applications, and right-click the panel: its menu opens too."
step "The window list has a button for foot and one for xterm. A click on a button"
step "focuses its window, a click on the focused one's minimises it, and one more brings"
step "it back."
step "A click on the second workspace in the switcher goes there, and a click on the"
step "first comes back to the windows."
note "The list shows every workspace's windows: that's 75, and not a failure here."
result "The panel's menus open, and the window list and the switcher answer a click"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The screensaver names"
if ! done_already "mate-screensaver isn't running, and Caminito owns org.mate.ScreenSaver"; then
if running mate-screensaver; then warn "mate-screensaver is running"; else ok "mate-screensaver isn't running"; fi
for name in org.mate.ScreenSaver org.freedesktop.ScreenSaver; do
  owner=$(busctl --user status "$name" 2>/dev/null | sed -n 's/^PID=//p' || true)
  if [[ -n $owner && $owner == "$CAMINITO_PID" ]]; then
    ok "$name is owned by pid $owner, which is Caminito"
  else
    warn "$name is owned by pid ${owner:-(nobody)}, and Caminito is pid $CAMINITO_PID"
  fi
done
result "mate-screensaver isn't running, and Caminito owns org.mate.ScreenSaver"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Maximising to the work area, on each output"
if ! done_already "A native and an X11 window maximise to the work area on each output"; then
running foot || native foot
say "Two GTK3 windows that ask to be maximised open on the focused window's output."
for which in first second; do
  step "Drag foot to the $which output, and click into it."
  pause "Press Enter once foot is there and focused"
  native "$HERE/gtk-window.py" "76 native, $which output"
  x11 "$HERE/gtk-window.py" "76 X11, $which output"
  sleep 4
  dump outputs
  dump windows
  step "Both windows fill that output between the panels, which stay visible, and"
  step "neither reaches under a panel or onto the other output."
  step "If they opened on the other output, say so in the note."
  pause "Press Enter once you've looked: the windows stay for the next output"
done
note "Expected (64): each window's geometry and frame together are its output's work"
note "area. Close the four windows after this."
result "A native and an X11 window maximise to the work area on each output"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "A cursor theme set in MATE's settings"
if ! done_already "A GTK3 app gets a cursor theme set in MATE's settings, natively and on XWayland"; then
say "The cursor themes installed:"
for d in /usr/share/icons/*/cursors; do say "  $(basename "$(dirname "$d")")"; done
show in_session gsettings get org.mate.peripherals-mouse cursor-theme
CURSOR=
printf '  %sA theme from the list that looks unlike the default (Enter for mate-black):%s ' "$BOLD" "$RESET"
read -r CURSOR || true
CURSOR=${CURSOR:-mate-black}
show in_session gsettings set org.mate.peripherals-mouse cursor-theme "$CURSOR"
sleep 2
show sh -c "systemctl --user show-environment | grep XCURSOR"
show in_session sh -c "xrdb -query | grep Xcursor"
rm -f "$STATE"/76-cursor-*.json
in_session env -u DISPLAY GDK_BACKEND=wayland "$HERE/gtk-window.py" "76 cursor, native" > "$STATE/76-cursor-native.json" 2>/dev/null &
in_session env -u WAYLAND_DISPLAY GDK_BACKEND=x11 "$HERE/gtk-window.py" "76 cursor, X11" > "$STATE/76-cursor-x11.json" 2>/dev/null &
sleep 4
show cat "$STATE/76-cursor-native.json" "$STATE/76-cursor-x11.json"
step "The pointer is $CURSOR's over the native window, over the X11 one, over their"
step "frames, over the panel and over the desktop."
note "Expected (71): cursor_theme is $CURSOR in both windows. Windows that were open"
note "before the change may keep the old one until the pointer leaves and enters them."
result "A GTK3 app gets a cursor theme set in MATE's settings, natively and on XWayland"
in_session gsettings reset org.mate.peripherals-mouse cursor-theme || true
say "The cursor theme is reset. Close the two windows."
pause
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Layer-shell keyboard modes (63)"
if ! done_already "A gtk-layer-shell demo's keyboard modes"; then
running foot || native foot
say "A demo with a text entry opens on the overlay layer, once for each mode. Before"
say "each one, click into foot so that it has the keyboard."
for mode in exclusive on_demand none; do
  pause "Press Enter, from foot having the keyboard, to open the $mode demo"
  native "$HERE/layer-demo.py" "$mode"
  sleep 2
  dump outputs | grep -E "^    [^ ]|$DEMO_NAMESPACE" || true
  case $mode in
    exclusive)
      step "Without a click, typing goes to the demo's entry, and none of it to foot."
      step "A click on foot doesn't take the keyboard from it."
      step "Press Escape: the demo closes, and typing goes to foot again." ;;
    on_demand)
      step "Typing still goes to foot. Click the demo's entry: now typing goes there."
      step "Click foot: typing goes to foot again. Close the demo with its button." ;;
    none)
      step "Typing goes to foot, before and after a click on the demo's entry."
      step "Close the demo with its button." ;;
  esac
  pause "Press Enter once the demo is closed"
  pkill -u "$(id -u)" -f "$HERE/layer-demo.py" || true
done
note "Expected (63): exclusive has the keyboard while it's mapped and gives it back to"
note "the focused window; on_demand has it from a click on it until a click on a window;"
note "none never has it. foot's frame stays drawn focused all the while."
result "A gtk-layer-shell demo's keyboard modes"
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "msd's xrdb -merge and Caminito's Xft resources (71, 47)"
if ! done_already "msd's xrdb -merge and Caminito's Xft resources don't get in each other's way"; then
# count_resources FILE prints how often each of Caminito's resources (47) is in a saved
# xrdb -query.
count_resources() {
  local name
  for name in Xft.dpi Xft.antialias Xft.hinting Xft.hintstyle Xft.rgba Xft.lcdfilter Xcursor.theme Xcursor.size; do
    printf '    %-16s %s\n' "$name" "$(grep -c "^$name:" "$1" || true)"
  done
}
# Saved when the session was found. A run that didn't find one saves it now.
[[ -s $XRDB_LOGIN ]] || in_session xrdb -query > "$XRDB_LOGIN" 2>&1 || warn "xrdb -query failed"
say "xrdb -query after login has $(wc -l < "$XRDB_LOGIN") lines. Caminito's, and how often each is there:"
count_resources "$XRDB_LOGIN"
show grep -E '^(Xft|Xcursor)\.' "$XRDB_LOGIN"
THEME=$(in_session gsettings get org.mate.interface gtk-theme | tr -d "'" || true)
THEME=${THEME:-Menta}
OTHER=TraditionalOk
[[ $THEME != "$OTHER" ]] || OTHER=Menta
[[ -d /usr/share/themes/$OTHER ]] || warn "$OTHER isn't installed (mate-themes has it)"
say "Changing the theme from $THEME to $OTHER."
show in_session gsettings set org.mate.interface gtk-theme "$OTHER"
sleep 4
in_session xrdb -query > "$STATE/76-xrdb-theme" 2>&1 || warn "xrdb -query failed"
say "xrdb -query after the theme change has $(wc -l < "$STATE/76-xrdb-theme") lines. Caminito's:"
count_resources "$STATE/76-xrdb-theme"
say "What changed:"
diff "$XRDB_LOGIN" "$STATE/76-xrdb-theme" | sed 's/^/    /' || true
note "Expected: each of Caminito's eight is there once, before and after, with the values"
note "of MATE's font and mouse settings, and the theme change touched only msd's colour"
note "lines (*background and the like). xterm and the GTK3 windows redraw in $OTHER."
result "msd's xrdb -merge and Caminito's Xft resources don't get in each other's way"
in_session gsettings set org.mate.interface gtk-theme "$THEME" || true
say "The theme is back to $THEME."
pause
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "63's open question: caja's desktop menu under the windows"
if ! done_already "caja's desktop menu and the windows that overlap it (63)"; then
running foot || native foot
step "Put foot beside some empty desktop, on the output with the icons."
step "Right-click the desktop close to foot's edge, so that the menu would reach over foot."
note "63 draws a popup in its surface's layer, so the menu of caja's desktop, on the"
note "bottom layer, is under foot. sway and niri draw such popups above the windows."
note "This one is yours to decide: say in the note what you saw and what you want."
result "caja's desktop menu and the windows that overlap it (63)"
fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Logging out from the panel"
if ! done_already "Logging out from the panel gives the tty back"; then
if [[ ! -e $LOGOUT_ASKED ]]; then
  say "Before the logout:"
  show loginctl list-sessions --no-pager
  show session_environment
  printf '%s\n%s\n' "$(bus_started)" "$(loginctl list-sessions --no-legend | awk -v user="$(id -un)" '$3 == user && $6 == "user"' | wc -l)" > "$LOGOUT_ASKED"
  step "In the panel: System, Log Out caminitotest…, then Log Out."
  warn "A wizard inside the session ends with it. Run it again from the tty and resume."
  pause "Press Enter once the session has ended"
fi
await_exit
{ read -r BUS_BEFORE; read -r LOGINS; } < "$LOGOUT_ASKED"
LEFT=$(session_environment | cut -d= -f1 | paste -sd, | sed 's/,/, /g')
show session_environment
if [[ $(bus_started) == "$BUS_BEFORE" ]]; then BUS="wasn't restarted"; else BUS="was restarted"; fi
say "The user's bus $BUS: it started at ${BUS_BEFORE:-(unknown)} before, and at $(bus_started) now."
UNSET=$(journalctl --user --since "$SINCE" -t caminito -o cat --no-pager 2>/dev/null | grep -c "didn't unset the environment" || true)
say "Caminito logged 'systemd didn't unset the environment' $UNSET times."
show sh -c "journalctl --user --since '$SINCE' -t caminito -o cat --no-pager | tail -n 6"
say "What is left of the session:"
pgrep -u "$(id -u)" -a | grep -vE 'systemd|\(sd-pam\)|dbus-(daemon|broker)|pgrep|sshd|bash|login|tty-login' | sed 's/^/    /' || ok "nothing"
step "Caminito's tty is back in text mode, at caminitotest's shell prompt."
note "Expected (61): only XDG_CURRENT_DESKTOP and XDG_SESSION_TYPE stay. More than"
note "those is 74's, and not a failure of this check, which is the tty."
# Before the result, which is what a resumed run skips this stage by.
record "For 74: the systemd environment after a logout on the tty" seen \
  "With $LOGINS logind session(s) of class user for caminitotest, the bus $BUS, 'didn't unset' was logged $UNSET times, and these stayed: ${LEFT:-none}."
result "Logging out from the panel gives the tty back"
fi

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Bare caminito --session, as the session file runs it"
if ! done_already "Bare caminito --session reaches the desktop and logs out"; then
if [[ ! -e $BARE_ASKED ]]; then
  bus_started > "$BARE_ASKED"
  say "The session file's Exec is bare caminito --session, with no --debug and stderr on"
  say "the terminal. Run it once more that way, on the tty:"
  step "caminito --session"
  step "Look that the desktop comes up as before, then log out from the panel."
  step "Then run this wizard again, and resume."
  note "Over ssh, leave the wizard here and press Enter after the logout instead."
  if ! confirm "Is the wizard on ssh, staying through the session?"; then
    printf '\n'; say "Stopping here. Run the wizard again after the logout."
    exit 0
  fi
  pause "Press Enter once that session has ended"
fi
CAMINITO_PID=$(pgrep -n -x -u "$(id -u)" caminito || true)
await_exit
LEFT=$(session_environment | cut -d= -f1 | paste -sd, | sed 's/,/, /g')
show session_environment
if [[ $(bus_started) == "$(cat "$BARE_ASKED")" ]]; then BUS="wasn't restarted"; else BUS="was restarted"; fi
say "The user's bus $BUS."
note "Caminito's stderr was the terminal, so what it logged is on the tty and not in the journal."
record "For 74: the systemd environment after the second logout" seen \
  "The bus $BUS, and these stayed: ${LEFT:-none}."
result "Bare caminito --session reaches the desktop and logs out"
fi

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Record the results"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r name verdict note <<< "$r"
  say "$verdict  $name${note:+ ($note)}"
done
if confirm "Write these down?"; then
  write_results
  rm -f "$PROGRESS" "$SESSION" "$LOGOUT_ASKED" "$BARE_ASKED"
  (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure, blocking 73 if M5's exit needs it: ${FAILED[*]}")
else
  SKIPPED+=("recording the results in ticket 76 (they stay in $PROGRESS)")
fi
SKIPPED+=("ticking 76's criteria from these results, and the same run in the virtual machine if it's to be had")
SKIPPED+=("the 'For 74' lines into 74's notes")
SKIPPED+=("63's question, as a ticket if the menu is to be drawn above the windows")
pause

finish
